<?php
session_start();
require_once __DIR__.'/../php/sd_authorization.php';
sdRequireRole('admin');
require_once '../php/conexao.php';require_once '../php/sd_service.php';$msg='';
if(empty($_SESSION['rules_csrf']))$_SESSION['rules_csrf']=bin2hex(random_bytes(24));
try{sdSchema($conexao);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['rules_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('CSRF inválido');
 $name=trim((string)($_POST['name']??''));$device=trim((string)($_POST['device_id']??''));$metric=trim((string)($_POST['metric']??''));$op=(string)($_POST['operator']??'');$threshold=filter_var($_POST['threshold']??null,FILTER_VALIDATE_FLOAT);$cooldown=filter_var($_POST['cooldown']??null,FILTER_VALIDATE_INT);$priority=(string)($_POST['priority']??'alta');
 if(!$name||mb_strlen($name)>100||!preg_match('/^[a-zA-Z0-9_.:-]{1,80}$/',$metric)||($device!==''&&!preg_match('/^[a-zA-Z0-9_.:-]{3,64}$/',$device))||!in_array($op,['gt','gte','lt','lte'],true)||$threshold===false||$cooldown===false||$cooldown<0||$cooldown>86400||!in_array($priority,['baixa','media','alta','critica'],true))throw new InvalidArgumentException('Dados inválidos');
 $device=$device===''?null:$device;$s=$conexao->prepare('INSERT INTO sd_iot_rules(name,device_id,metric,operator,threshold,priority,cooldown_seconds) VALUES(?,?,?,?,?,?,?)');$s->bind_param('ssssdsi',$name,$device,$metric,$op,$threshold,$priority,$cooldown);$s->execute();$s->close();$msg='Regra cadastrada.';
}
$rules=$conexao->query('SELECT * FROM sd_iot_rules ORDER BY id DESC LIMIT 100')->fetch_all(MYSQLI_ASSOC);
}catch(Throwable $e){$msg=$e->getMessage();$rules=[];}
function he($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Regras IoT</title><link rel="stylesheet" href="../assets/css/sd.css"><link rel="stylesheet" href="../assets/css/confinter-sd-refinement.css"><link rel="stylesheet" href="assets/css/confinter-operations-2026.css"><link rel="stylesheet" href="assets/css/admin-ui.css"><link rel="stylesheet" href="assets/css/confinter-operations-2026.css"></head><body><?php include __DIR__.'/navbar.php';  ?><div class="page-wrapper"><main class="sd-wrap sd-admin-surface"><a href="service-desk.php">← Chamados</a><h1>Motor de regras IoT</h1><?php if($msg):?><p class="notice"><?=he($msg)?></p><?php endif;?><section class="sd-card"><h2>Nova regra</h2><form method="post"><input type="hidden" name="csrf" value="<?=he($_SESSION['rules_csrf'])?>"><label>Nome<input required name="name" maxlength="100"></label><label>Dispositivo (vazio: qualquer)<input name="device_id"></label><label>Métrica<input name="metric" required placeholder="temperatura"></label><label>Comparação<select name="operator"><option value="gt">Maior que</option><option value="gte">Maior ou igual</option><option value="lt">Menor que</option><option value="lte">Menor ou igual</option></select></label><label>Limite<input type="number" step="any" name="threshold" required></label><label>Prioridade<select name="priority"><option>alta</option><option>critica</option><option>media</option><option>baixa</option></select></label><label>Cooldown (segundos)<input type="number" min="0" max="86400" name="cooldown" value="900" required></label><button>Salvar regra</button></form></section><section class="sd-card"><h2>Regras cadastradas</h2><div class="sd-table-scroll"><table><thead><tr><th>Nome</th><th>Dispositivo</th><th>Métrica</th><th>Condição</th><th>Cooldown</th></tr></thead><tbody><?php foreach($rules as $r):?><tr><td><?=he($r['name'])?></td><td><?=he($r['device_id']??'Todos')?></td><td><?=he($r['metric'])?></td><td><?=he($r['operator'])?> <?=he($r['threshold'])?></td><td><?=he($r['cooldown_seconds'])?>s</td></tr><?php endforeach;?></tbody></table></div></section></main><?php include __DIR__.'/footer.php'; ?></body></html>